/**
 * Manages authentication state and token refresh operations.
 */
export class AuthManager {
  constructor(options = {}) {
    /**
     * Callbacks for token persistence.
     * onGetToken: () => Promise<string>
     * onSaveToken: (token: string) => Promise<void>
     * onRefreshToken: () => Promise<string>
     */
    this.onGetToken = options.onGetToken || (() => Promise.resolve(null));
    this.onSaveToken = options.onSaveToken || (() => Promise.resolve());
    this.onRefreshToken = options.onRefreshToken || (() => Promise.reject(new Error('Refresh token function not defined')));
    this.onAuthError = options.onAuthError || (() => {});

    // State for managing concurrent refresh requests
    this.isRefreshing = false;
    this.refreshQueue = [];
  }

  async getToken() {
    return await this.onGetToken();
  }

  async saveToken(token) {
    return await this.onSaveToken(token);
  }

  /**
   * Refreshes the token and notifies all pending requests in the queue.
   */
  async refreshToken() {
    if (this.isRefreshing) {
      return new Promise((resolve, reject) => {
        this.refreshQueue.push({ resolve, reject });
      });
    }

    this.isRefreshing = true;

    try {
      const newToken = await this.onRefreshToken();
      await this.saveToken(newToken);
      
      // Resolve all queued requests with the new token
      const queue = [...this.refreshQueue];
      this.refreshQueue = [];
      queue.forEach(p => p.resolve(newToken));
      
      return newToken;
    } catch (error) {
      // Reject all queued requests and trigger auth error callback
      const queue = [...this.refreshQueue];
      this.refreshQueue = [];
      queue.forEach(p => p.reject(error));
      this.onAuthError(error);
      throw error;
    } finally {
      this.isRefreshing = false;
    }
  }
}

